61: template<class T>
62: inline constexpr bool has_st_mtimespec = requires(const T &s) { s.st_mtimespec; };
63: 
64: template<typename Stat>
65: const struct timespec &mtim(const Stat &stbuf)
66: {
67:     static_assert(has_st_mtim<Stat> || has_st_mtimespec<Stat>, "stat must contain st_mtim or st_mtimespec");
68: 
69:     if constexpr (has_st_mtim<Stat>) {
70:         return stbuf.st_mtim;
71:     } else {
72:         // Mac OS X uses a different field name than POSIX and this makes it work
73:         return stbuf.st_mtimespec;
74:     }
75: }
