85: static bool makeFileDescriptorCloexec(int fd)
86: {
87: #    ifdef FD_CLOEXEC
88:     int flags = fcntl(fd, F_GETFD);
89:     if (flags >= 0 && !(flags & FD_CLOEXEC)) {
90:         flags = fcntl(fd, F_SETFD, flags | FD_CLOEXEC);
91:     }
92: 
93:     return flags >= 0;
94: #    else
95:     return true;
96: #    endif
97: }
98: 
99: static int openFileDescriptor(const char *path, int flags)
100: {
101: #    ifdef O_CLOEXEC
102:     return open(path, flags | O_CLOEXEC);
103: #    else
104:     int fd = open(path, flags);
105:     if (fd == -1)
106:         return fd;
107: 
108:     if (!makeFileDescriptorCloexec(fd)) {
109:         close(fd);
110:         return -1;
111:     }
112: 
113:     return fd;
114: #    endif
115: }
116: 
