119: FILE *openFile(const char *path, const char *mode)
120: {
121: #ifdef _WIN32
122:     OSVERSIONINFO version;
123:     wchar_t wPath[MAX_PATH + 1];
124:     char nPath[MAX_PATH + 1];
125:     wchar_t wMode[8];
126:     const char *p;
127:     size_t i;
128: 
129:     // NB: _wfopen is only available in NT
130:     version.dwOSVersionInfoSize = sizeof(version);
131:     GetVersionEx(&version);
132:     if (version.dwPlatformId == VER_PLATFORM_WIN32_NT) {
133:         for (p = path, i = 0; *p && i < MAX_PATH; ++i) {
134:             if ((p[0] & 0xe0) == 0xc0 && p[1] && (p[1] & 0xc0) == 0x80) {
135:                 wPath[i] = (wchar_t)(((p[0] & 0x1f) << 6) | (p[1] & 0x3f));
136:                 p += 2;
137:             } else if ((p[0] & 0xf0) == 0xe0 && p[1] && (p[1] & 0xc0) == 0x80 && p[2] && (p[2] & 0xc0) == 0x80) {
138:                 wPath[i] = (wchar_t)(((p[0] & 0x0f) << 12) | ((p[1] & 0x3f) << 6) | (p[2] & 0x3f));
139:                 p += 3;
140:             } else {
141:                 wPath[i] = (wchar_t)(p[0] & 0xff);
142:                 p += 1;
143:             }
144:         }
145:         wPath[i] = (wchar_t)0;
146:         for (i = 0; (i < sizeof(mode) - 1) && mode[i]; ++i) {
147:             wMode[i] = (wchar_t)(mode[i] & 0xff);
148:         }
149:         wMode[i] = (wchar_t)0;
150:         return _wfopen(wPath, wMode);
151:     } else {
152:         for (p = path, i = 0; *p && i < MAX_PATH; ++i) {
153:             if ((p[0] & 0xe0) == 0xc0 && p[1] && (p[1] & 0xc0) == 0x80) {
154:                 nPath[i] = (char)(((p[0] & 0x1f) << 6) | (p[1] & 0x3f));
155:                 p += 2;
156:             } else if ((p[0] & 0xf0) == 0xe0 && p[1] && (p[1] & 0xc0) == 0x80 && p[2] && (p[2] & 0xc0) == 0x80) {
157:                 nPath[i] = (char)(((p[1] & 0x3f) << 6) | (p[2] & 0x3f));
158:                 p += 3;
159:             } else {
160:                 nPath[i] = p[0];
161:                 p += 1;
162:             }
163:         }
164:         nPath[i] = '\0';
165:         return fopen(nPath, mode);
166:     }
167: #else
168:     // First try to atomically open the file with CLOEXEC
169:     const std::string modeStr = mode + "e"s;
170:     FILE *file = fopen(path, modeStr.c_str());
171:     if (file != nullptr) {
172:         return file;
173:     }
174: 
175:     // Fall back to the provided mode and apply CLOEXEC afterwards
176:     file = fopen(path, mode);
177:     if (file == nullptr) {
178:         return nullptr;
179:     }
180: 
181:     if (!makeFileDescriptorCloexec(fileno(file))) {
182:         fclose(file);
183:         return nullptr;
184:     }
185: 
186:     return file;
187: #endif
188: }
