190: char *getLine(char *buf, int size, FILE *f)
191: {
192:     int c, i;
193: 
194:     i = 0;
195:     while (i < size - 1) {
196:         if ((c = fgetc(f)) == EOF) {
197:             break;
198:         }
199:         buf[i++] = static_cast<char>(c);
200:         if (c == '\x0a') {
201:             break;
202:         }
203:         if (c == '\x0d') {
204:             c = fgetc(f);
205:             if (c == '\x0a' && i < size - 1) {
206:                 buf[i++] = static_cast<char>(c);
207:             } else if (c != EOF) {
208:                 ungetc(c, f);
209:             }
210:             break;
211:         }
212:     }
213:     buf[i] = '\0';
214:     if (i == 0) {
215:         return nullptr;
216:     }
217:     return buf;
218: }
