220: int Gfseek(FILE *f, Goffset offset, int whence)
221: {
222: #if HAVE_FSEEKO
223:     return fseeko(f, offset, whence);
224: #elif HAVE_FSEEK64
225:     return fseek64(f, offset, whence);
226: #elif defined(__MINGW32__)
227:     return fseeko64(f, offset, whence);
228: #elif defined(_WIN32)
229:     return _fseeki64(f, offset, whence);
230: #else
