252: #if HAVE_FSEEKO
253:     return (std::numeric_limits<off_t>::max)();
254: #elif HAVE_FSEEK64 || defined(__MINGW32__)
255:     return (std::numeric_limits<off64_t>::max)();
256: #elif defined(_WIN32)
257:     return (std::numeric_limits<__int64>::max)();
258: #else
