274: int GooFile::read(char *buf, int n, Goffset offset) const
275: {
276:     DWORD m;
277: 
278:     LARGE_INTEGER largeInteger = {};
279:     largeInteger.QuadPart = offset;
280: 
281:     OVERLAPPED overlapped = {};
282:     overlapped.Offset = largeInteger.LowPart;
283:     overlapped.OffsetHigh = largeInteger.HighPart;
284: 
285:     return FALSE == ReadFile(handle, buf, n, &m, &overlapped) ? -1 : m;
286: }
