240: std::unique_ptr<SysFontInfo> SysFontList::makeWindowsFont(const char *name, int fontNum, const char *path)
241: {
242:     int n;
243:     bool bold, italic, oblique, fixedWidth;
244:     char c;
245:     SysFontType type;
246:     GooString substituteName;
247: 
248:     n = strlen(name);
249:     bold = italic = oblique = fixedWidth = false;
250: 
251:     // remove trailing ' (TrueType)'
252:     if (n > 11 && !strncmp(name + n - 11, " (TrueType)", 11)) {
253:         n -= 11;
254:     }
255: 
256:     // remove trailing ' (OpenType)'
257:     if (n > 11 && !strncmp(name + n - 11, " (OpenType)", 11)) {
258:         n -= 11;
259:     }
260: 
261:     // remove trailing ' Italic'
262:     if (n > 7 && !strncmp(name + n - 7, " Italic", 7)) {
263:         n -= 7;
264:         italic = true;
265:     }
266: 
267:     // remove trailing ' Oblique'
268:     if (n > 8 && !strncmp(name + n - 8, " Oblique", 8)) {
269:         n -= 8;
270:         oblique = true;
271:     }
272: 
273:     // remove trailing ' Bold'
274:     if (n > 5 && !strncmp(name + n - 5, " Bold", 5)) {
275:         n -= 5;
276:         bold = true;
277:     }
278: 
279:     // remove trailing ' Regular'
280:     if (n > 8 && !strncmp(name + n - 8, " Regular", 8)) {
281:         n -= 8;
282:     }
283: 
284:     // the familyname cannot indicate whether a font is fixedWidth or not.
285:     // some well-known fixedWidth typeface family names or keyword are checked.
286:     if (strstr(name, "Courier") || strstr(name, "Fixed") || (strstr(name, "Mono") && !strstr(name, "Monotype")) || strstr(name, "Typewriter"))
287:         fixedWidth = true;
288:     else
289:         fixedWidth = false;
290: 
291:     //----- normalize the font name
292:     std::unique_ptr<GooString> s = std::make_unique<GooString>(name, n);
293:     size_t i = 0;
294:     while (i < s->size()) {
295:         c = s->getChar(i);
296:         if (c == ' ' || c == ',' || c == '-') {
297:             s->erase(i, 1);
298:         } else {
299:             ++i;
300:         }
301:     }
302: 
303:     if (!strcasecmp(path + strlen(path) - 4, ".ttc")) {
304:         type = sysFontTTC;
305:     } else {
306:         type = sysFontTTF;
307:     }
308: 
309:     return std::make_unique<SysFontInfo>(std::move(s), bold, italic, oblique, fixedWidth, std::make_unique<GooString>(path), type, fontNum, substituteName.copy());
310: }
