312: static std::string *replaceSuffix(std::string *path, const char *suffixA, const char *suffixB)
313: {
314:     int suffLenA = strlen(suffixA);
315:     int suffLenB = strlen(suffixB);
316:     int baseLenA = path->size() - suffLenA;
317:     int baseLenB = path->size() - suffLenB;
318: 
319:     if (!strcasecmp(path->c_str() + baseLenA, suffixA)) {
320:         path->erase(baseLenA, suffLenA);
321:         path->append(suffixB);
322:     } else if (!strcasecmp(path->c_str() + baseLenB, suffixB)) {
323:         path->erase(baseLenB, suffLenB);
324:         path->append(suffixA);
325:     }
326: 
327:     return path;
328: }
