330: void GlobalParams::setupBaseFonts(const char *dir)
331: {
332:     if (baseFontsInitialized)
333:         return;
334:     baseFontsInitialized = true;
335: 
336:     const std::string winFontDir = GetWindowsFontDir();
337: 
338:     std::vector<std::string> fontDirs;
339:     if (dir) {
340:         fontDirs.emplace_back(dir);
341:     }
342:     if (!winFontDir.empty()) {
343:         fontDirs.emplace_back(winFontDir);
344:     }
345: 
346:     for (int i = 0; displayFontTab[i].name; ++i) {
347:         if (fontFiles.count(displayFontTab[i].name) > 0)
348:             continue;
349: 
350:         const GooString fontName = GooString(displayFontTab[i].name);
351: 
352:         bool fontFound = false;
353:         for (const std::string &fontDir : fontDirs) {
354:             for (const std::string &fileName : displayFontTab[i].fileNames) {
355:                 std::string fontPath = appendToPath(fontDir, fileName);
356:                 if (FileExists(fontPath.c_str()) || FileExists(replaceSuffix(&fontPath, ".pfb", ".pfa")->c_str()) || FileExists(replaceSuffix(&fontPath, ".ttc", ".ttf")->c_str())) {
357:                     addFontFile(fontName.toStr(), fontPath);
358:                     fontFound = true;
359:                     break;
360:                 }
361:             }
362: 
363:             if (fontFound) {
364:                 break;
365:             }
366:         }
367: 
368:         if (!fontFound && displayFontTab[i].warnIfMissing) {
369:             error(errSyntaxError, -1, "No display font for '{0:s}'", displayFontTab[i].name);
370:         }
371:     }
372:     if (!winFontDir.empty()) {
373:         sysFonts->scanWindowsFonts(winFontDir);
374:     }
375: 
376:     std::string dataRoot = !popplerDataDir.empty() ? popplerDataDir : std::string { POPPLER_DATADIR };
377:     const std::string fileName = std::string(dataRoot).append("/cidfmap");
378: 
379:     // try to open file
380:     const std::unique_ptr<GooFile> file = GooFile::open(fileName);
381: 
382:     if (file) {
383:         Parser *parser;
384:         parser = new Parser(nullptr, std::make_unique<FileStream>(file.get(), 0, false, file->size(), Object::null()), true);
385:         Object obj1 = parser->getObj();
386:         while (!obj1.isEOF()) {
387:             Object obj2 = parser->getObj();
388:             if (obj1.isName()) {
389:                 // Substitutions
390:                 if (obj2.isDict()) {
391:                     Object obj3 = obj2.getDict()->lookup("Path");
392:                     if (obj3.isString())
393:                         addFontFile(GooString(obj1.getName()).toStr(), obj3.getString());
394:                     // Aliases
395:                 } else if (obj2.isName()) {
396:                     substFiles.emplace(obj1.getName(), obj2.getName());
397:                 }
398:             }
399:             obj1 = parser->getObj();
400:             // skip trailing ';'
401:             while (obj1.isCmd(";")) {
402:                 obj1 = parser->getObj();
403:             }
404:         }
405:         delete parser;
406:     }
407: }
