409: static const char *findSubstituteName(const GfxFont *font, const std::unordered_map<std::string, std::string> &fontFiles, const std::unordered_map<std::string, std::string> &substFiles, const char *origName)
410: {
411:     assert(origName);
412:     if (!origName)
413:         return nullptr;
414:     GooString *name2 = new GooString(origName);
415:     int n = strlen(origName);
416:     // remove trailing "-Identity-H"
417:     if (n > 11 && !strcmp(name2->c_str() + n - 11, "-Identity-H")) {
418:         name2->erase(n - 11, 11);
419:         n -= 11;
420:     }
421:     // remove trailing "-Identity-V"
422:     if (n > 11 && !strcmp(name2->c_str() + n - 11, "-Identity-V")) {
423:         name2->erase(n - 11, 11);
424:         n -= 11;
425:     }
426:     const auto substFile = substFiles.find(name2->c_str());
427:     if (substFile != substFiles.end()) {
428:         delete name2;
429:         return substFile->second.c_str();
430:     }
431: 
432:     /* TODO: try to at least guess bold/italic/bolditalic from the name */
433:     delete name2;
434:     if (font->isCIDFont()) {
435:         const GooString *collection = ((GfxCIDFont *)font)->getCollection();
436: 
437:         const char *name3 = nullptr;
438:         if (!collection->compare("Adobe-CNS1"))
439:             name3 = DEFAULT_CID_FONT_AC1_MSWIN;
440:         else if (!collection->compare("Adobe-GB1"))
441:             name3 = DEFAULT_CID_FONT_AG1_MSWIN;
442:         else if (!collection->compare("Adobe-Japan1"))
443:             name3 = DEFAULT_CID_FONT_AJ1_MSWIN;
444:         else if (!collection->compare("Adobe-Japan2"))
445:             name3 = DEFAULT_CID_FONT_AJ2_MSWIN;
446:         else if (!collection->compare("Adobe-Korea1"))
447:             name3 = DEFAULT_CID_FONT_AK1_MSWIN;
448: 
449:         if (name3 && fontFiles.count(name3) != 0)
450:             return name3;
451: 
452:         if (fontFiles.count(DEFAULT_CID_FONT_MSWIN) != 0)
453:             return DEFAULT_CID_FONT_MSWIN;
454:     }
455:     return DEFAULT_SUBSTITUTE_FONT;
